<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Control de entrega</title><style>
@page{size:A4 landscape;margin:8mm}*{box-sizing:border-box}body{margin:0;font-family:DejaVu Sans,sans-serif;color:#111;font-size:8pt}.page{page-break-after:always}.page:last-child{page-break-after:auto}.control{width:100%;border-collapse:collapse;table-layout:fixed}.control th{padding:2mm 1mm;background:#477a32;color:#fff;border:.25mm solid #315722;text-transform:uppercase}.control td{height:13mm;padding:1.5mm;border:.25mm solid #999;vertical-align:middle;line-height:1.15}.control tbody tr:nth-child(even){background:#f4f7f2}.number{width:4%;text-align:center}.customer{width:17%}.address{width:23%}.district{width:11%}.program{width:14%}.phone{width:11%;text-align:center}.observation{width:20%}.footer{width:100%;margin-top:2mm;color:#666;font-size:7pt}.footer .page-number{text-align:right}.empty{text-align:center;margin-top:30mm}
